svg.script:
(async function () {
  'use strict';
  var host = location.hostname.endsWith('jsdelivr.net') ? location.host : 'cdn.jsdelivr.net';
  var base = 'https://' + host + '/gh/ParrrotVR/tbw-web@';
  var fallback = base + 'portal/index.svg';
  var link = document.getElementById('open');
  link.href = fallback;
  var controller = new AbortController();
  var timer = setTimeout(function () { controller.abort(); }, 8000);
  try {
    var response = await fetch('https://api.github.com/repos/ParrrotVR/tbw-web/git/ref/heads/portal?t=' + Date.now(), {
      cache: 'no-store', credentials: 'omit', signal: controller.signal
    });
    if (!response.ok) throw new Error('Version lookup unavailable');
    var version = await response.json();
    var commit = version.object && version.object.sha;
    if (!/^[a-f0-9]{40}$/.test(commit || '')) throw new Error('Invalid version');
    var target = base + commit + '/index.svg' + location.search + location.hash;
    link.href = target;
    document.getElementById('status').textContent = 'Opening Harbor…';
    location.replace(target);
  } catch (_) {
    document.getElementById('status').textContent = 'Opening Harbor…';
    location.replace(fallback + location.search + location.hash);
  } finally { clearTimeout(timer); }
})();
